import { z } from 'zod';
export const EMAIL_REQUIRED: string;
export const EMAIL_INVALID: string;
export const emailSchema: z.ZodType<string, string>;
export const loginEmailSchema: z.ZodType<string, string>;
export const mailboxEmailSchema: z.ZodType<string, string>;
export const optionalEmailSchema: z.ZodType<string | null | undefined, unknown>;
export function normalizeEmail(value: string): string;
export function validateEmail(value: unknown, options?: { required?: boolean; context?: 'login' }): string;
export const usPhoneSchema: z.ZodType<string, string>;
export const usLabPhoneSchema: z.ZodType<string, unknown>;
export function validateUsLabPhone(value: unknown): string;
export const optionalUsPhoneSchema: z.ZodType<string | null | undefined, unknown>;
export function validateUsPhone(value: unknown, options?: { required?: boolean }): string;
export const patientRequiredSchema: z.ZodObject<{ first_name: z.ZodString; last_name: z.ZodString; address: z.ZodString; postal_code: z.ZodString }>;
export const patientDobSchema: z.ZodType<Date | null | undefined, unknown>;
export const patientGenderSchema: z.ZodType<'Male' | 'Female' | 'Other' | null | undefined, unknown>;
export type PatientDetails = { first_name: string; last_name: string; address: string; postal_code: string;
    email?: string | null; phone?: string | null; secondary_phone?: string | null; dob?: Date | null; gender?: 'Male' | 'Female' | 'Other' | null };
export const patientDetailsSchema: z.ZodType<PatientDetails, unknown>;
export const patientOrderDetailsSchema: z.ZodType<PatientDetails & { email: string; phone: string }, unknown>;
export const profileNameSchema: z.ZodString;
export const profileFormSchema: z.ZodType<{ name: string; email: string }, unknown>;
export function patientFieldErrors(value: unknown): Record<string, string>;
export function patientOrderFieldErrors(value: unknown): Record<string, string>;
export function profileFieldErrors(value: unknown): Record<string, string>;
